use std::{fs,os::unix::fs::PermissionsExt,path::PathBuf,sync::atomic::{AtomicUsize,Ordering}};
use uasf_queue::{config::{Config,Route,binding},sys};
static NEXT:AtomicUsize=AtomicUsize::new(0);
struct Fixture(PathBuf);
impl Fixture{fn new()->Self{let p=std::env::temp_dir().join(format!("queue-binding-{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::SeqCst)));fs::create_dir(&p).unwrap();for n in ["bundle","store"]{fs::create_dir(p.join(n)).unwrap();fs::set_permissions(p.join(n),fs::Permissions::from_mode(0o700)).unwrap();}Self(p)}fn config(&self)->Config{let root=self.0.join("store");Config{version:1,bundle:self.0.join("bundle"),routes:vec![Route{id:"core".into(),kind:"core".into(),binary:PathBuf::from("/usr/bin/true").canonicalize().unwrap(),root:root.clone(),args:vec!["--index".into(),root.join("index.sqlite").to_str().unwrap().into(),"--persistent".into(),root.join("persistent.sqlite").to_str().unwrap().into()]}]}}}
impl Drop for Fixture{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
#[test]fn binding_is_idempotent_and_cannot_replace_another_route(){let f=Fixture::new();let c=f.config();c.bind().unwrap();c.bind().unwrap();let mut other=c.clone();other.routes[0].id="other".into();assert!(other.bind().is_err());assert_eq!(binding(&c.routes[0].root).unwrap().unwrap().route.id,"core");}
#[test]fn unbind_requires_service_and_guardian_to_be_gone(){let f=Fixture::new();let c=f.config();c.bind().unwrap();let lock=sys::lock(&c.bundle.join("slot-0")).unwrap();assert!(c.unbind().is_err());drop(lock);let lock=sys::lock(&c.bundle.join("service.lock")).unwrap();assert!(c.unbind().is_err());drop(lock);c.unbind().unwrap();assert!(binding(&c.routes[0].root).unwrap().is_none());}
#[test]fn replaced_bundle_inode_and_unsafe_binding_mode_are_refused(){let f=Fixture::new();let c=f.config();c.bind().unwrap();let p=c.routes[0].root.join(".uasf-queue.json");fs::set_permissions(&p,fs::Permissions::from_mode(0o644)).unwrap();assert!(binding(&c.routes[0].root).is_err());fs::set_permissions(&p,fs::Permissions::from_mode(0o600)).unwrap();fs::rename(&c.bundle,f.0.join("old")).unwrap();fs::create_dir(&c.bundle).unwrap();fs::set_permissions(&c.bundle,fs::Permissions::from_mode(0o700)).unwrap();assert!(binding(&c.routes[0].root).is_err());}
